        c.add("find", SPEC, f"pieces per set of requirement {base.requirement}", 17, p)
    if base.usable_travel:
        reserves = resolve.latest_by_key(facts.end_reserves, facts, [],
                                         key=lambda r: (norm_key(r.key), norm_key(r.revision)))
